<script lang="ts">import { onMount } from 'svelte'; import { base } from '$app/paths'; import { addRenown, completeRound, initialRoundState, type RoundState } from '$lib/endgame/round'; let state: RoundState = initialRoundState(); onMount(() => { const p = new URLSearchParams(location.search); if (p.get('round') === '1') state = completeRound(state); if (p.get('win') === '1') state = addRenown(state, 'aragorn', 10); });</script>
<main><section><p>Round and Endgame</p><h1>{state.ended ? 'The final Chronicle is written.' : `Round ${state.round}`}</h1><p>First player: <strong>{state.firstPlayer}</strong> · Aragorn Renown: <strong>{state.renown.aragorn}</strong></p><div><a href={`${base}/endgame/?round=1`} data-sveltekit-reload>Complete round</a><a href={`${base}/endgame/?win=1`} data-sveltekit-reload>Trigger 10 Renown</a></div>{#if state.ended}<p role="status">Winner: <strong>{state.winner}</strong>. Rematch is available.</p>{/if}</section></main>
